import csv
import io
import posixpath
from datetime import date, datetime
from decimal import Decimal, ROUND_HALF_UP

def balance(p):
    seen=set(); total=0
    for e in p:
        if e['id'] not in seen: total+=e['amount'] if e['kind']=='payment' else -e['amount']; seen.add(e['id'])
    return total

def active(p):
    return sorted(s['id'] for s in p['subscriptions'] if s['start']<=p['now']<s['end'])

